	avgLoad := float64(totalLoad) / float64(len(snapshots))

	if avgLoad > 0 {
		for _, snap := range snapshots {
			load := float64(snap.EffectiveLoad())
			// Apply penalty when load exceeds 2x average
			if load > 2.0*avgLoad {
				overloadFactor := load / avgLoad
				penalty := 1.0 / overloadFactor
				if penalty < 0.2 {
					penalty = 0.2  // Cap penalty to avoid complete exclusion
				}
				scores[snap.ID] *= penalty
			}
